import { useState } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Container,
  FormControlLabel,
  Radio,
  RadioGroup,
  Stack,
  Tab,
  Tabs,
  Typography,
} from "@mui/material";
import type { HomePlans } from "../types/home";

export default function Plans({ data }: { data?: HomePlans | null }) {
  const [tab, setTab] = useState(0);
  const [selected, setSelected] = useState<Record<number, string>>({});

  if (!data) return null;
  const current = data.tabs?.[tab];

  return (
    <Box sx={{ py: { xs: 6, md: 8 }, backgroundColor: "#f4f7fb" }}>
      <Container maxWidth="lg">
        <Typography sx={{ textAlign: "center", color: "#17224d", fontSize: { xs: 22, md: 32 }, fontWeight: 600, mb: 4 }}>
          {data.title}{" "}
          {data.highlight ? (
            <Box component="span" sx={{ color: "#759ae1" }}>
              {data.highlight}
            </Box>
          ) : null}
        </Typography>
        <Tabs
          value={tab}
          onChange={(_, value) => setTab(value)}
          variant="scrollable"
          scrollButtons="auto"
          sx={{
            mb: 4,
            "& .MuiTab-root": { color: "#759ae1", fontWeight: 600 },
            "& .Mui-selected": { color: "#759ae1" },
          }}
        >
          {(data.tabs || []).map((item) => (
            <Tab key={item.id || item.name} label={item.name} />
          ))}
        </Tabs>
        <Stack direction="row" flexWrap="wrap" useFlexGap spacing={3} justifyContent="center">
          {(current?.plans || []).map((plan) => {
            const key = plan.id || 0;
            const value = selected[key] || plan.prices?.[0]?.duration || "";
            return (
              <Card key={plan.id || plan.title} sx={{ width: { xs: "100%", md: 460 }, borderRadius: "16px" }}>
                <CardContent>
                  <Typography sx={{ fontWeight: 700, fontSize: 20, color: "#17224d", mb: 2 }}>
                    {plan.title}
                  </Typography>
                  <RadioGroup
                    value={value}
                    onChange={(event) => setSelected((prev) => ({ ...prev, [key]: event.target.value }))}
                  >
                    {(plan.prices || []).map((price) => (
                      <Stack
                        key={price.id || price.duration}
                        direction="row"
                        justifyContent="space-between"
                        alignItems="center"
                        sx={{ borderBottom: "1px solid #eee", py: 1 }}
                      >
                        <FormControlLabel value={price.duration} control={<Radio />} label={price.duration} />
                        <Box sx={{ textAlign: "right" }}>
                          <Typography sx={{ color: "#759ae1", fontWeight: 700 }}>{price.price}</Typography>
                          {price.strikePrice ? (
                            <Typography sx={{ textDecoration: "line-through", color: "#9aa3b2", fontSize: 14 }}>
                              {price.strikePrice}
                            </Typography>
                          ) : null}
                        </Box>
                      </Stack>
                    ))}
                  </RadioGroup>
                  {plan.buyUrl ? (
                    <Button
                      fullWidth
                      variant="contained"
                      href={plan.buyUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      sx={{ mt: 2, backgroundColor: "#759ae1", "&:hover": { backgroundColor: "#5f86d4" } }}
                    >
                      Buy Plan
                    </Button>
                  ) : null}
                </CardContent>
              </Card>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
